#!/usr/bin/env python3
"""Independent naive reference implementation used only for testing."""
import hashlib
import ipaddress
import json
import re
import sys

ID_RE = re.compile(r'^[A-Za-z][A-Za-z0-9_-]{0,31}$')
DOC = ipaddress.IPv6Network('2001:db8::/32')


class Bad(Exception):
    pass


def hook(pairs):
    d = {}
    for k, v in pairs:
        if k in d:
            raise Bad('dup')
        d[k] = v
    return d


def jload(raw):
    if raw.startswith(b'\xef\xbb\xbf'):
        raise Bad('bom')
    t = raw.decode('utf-8')
    if t.startswith('\ufeff'):
        raise Bad('bom')
    return json.loads(t, object_pairs_hook=hook,
                      parse_constant=lambda x: (_ for _ in ()).throw(Bad('nf')))


def isint(v):
    return isinstance(v, int) and not isinstance(v, bool)


def rng(v, lo, hi, what):
    if not isint(v) or v < lo or v > hi:
        raise Bad(what)
    return v


def addr6(text):
    """Return int value if a strict doc-prefix IPv6 text, else None."""
    if not isinstance(text, str):
        return None
    for ch in text:
        if ch in ' \t\r\n\v\f%':
            return None
        if not (ch in '0123456789abcdefABCDEF:.'):
            return None
    try:
        a = ipaddress.IPv6Address(text)
    except Exception:
        return None
    if not a in DOC:
        return None
    return int(a)


def fmt(v):
    return str(ipaddress.IPv6Address(v))


def load_manifest(path):
    raw = open(path, 'rb').read()
    if len(raw) > 1024 * 1024:
        raise Bad('manifest too big')
    doc = jload(raw)
    if not isinstance(doc, dict):
        raise Bad('not object')
    if set(doc) != {'version', 'seed', 'low_count', 'attempts', 'spacing_ms',
                    'timeout_ms', 'windows'}:
        raise Bad('keys')
    if not isint(doc['version']) or doc['version'] != 1:
        raise Bad('version')
    seed = rng(doc['seed'], 0, 2 ** 64 - 1, 'seed')
    low = rng(doc['low_count'], 1, 32, 'low_count')
    att = rng(doc['attempts'], 1, 3, 'attempts')
    sp = rng(doc['spacing_ms'], 1, 1000, 'spacing_ms')
    to = rng(doc['timeout_ms'], 1, 1000000, 'timeout_ms')
    W = doc['windows']
    if not isinstance(W, list) or len(W) > 8:
        raise Bad('windows')
    wins = []
    ids = set()
    total = 0
    for w in W:
        if not isinstance(w, dict) or set(w) != {'id', 'start_ms', 'scopes'}:
            raise Bad('window keys')
        wid = w['id']
        if not isinstance(wid, str) or not ID_RE.match(wid) or wid in ids:
            raise Bad('wid')
        ids.add(wid)
        st = rng(w['start_ms'], 0, 10 ** 12, 'start_ms')
        S = w['scopes']
        if not isinstance(S, list) or len(S) > 32:
            raise Bad('scopes')
        scopes = []
        sids = set()
        bases = set()
        for s in S:
            if not isinstance(s, dict) or set(s) != {'id', 'prefix', 'subnets'}:
                raise Bad('scope keys')
            sid = s['id']
            if not isinstance(sid, str) or not ID_RE.match(sid) or sid in sids:
                raise Bad('sid')
            sids.add(sid)
            p = s['prefix']
            if not isinstance(p, str) or p.count('/') != 1:
                raise Bad('prefix')
            atxt, ltxt = p.split('/')
            if ltxt not in ('56', '64'):
                raise Bad('plen')
            pl = int(ltxt)
            v = addr6(atxt)
            if v is None:
                raise Bad('prefix addr')
            net = ipaddress.IPv6Network('%s/%d' % (fmt(v), pl), strict=True)
            subs = s['subnets']
            if not isinstance(subs, list) or not all(isint(x) for x in subs):
                raise Bad('subnets')
            if len(set(subs)) != len(subs):
                raise Bad('dup subnets')
            if pl == 56:
                if not (1 <= len(subs) <= 256) or any(x < 0 or x > 255 for x in subs):
                    raise Bad('subnet range')
            else:
                if subs != [0]:
                    raise Bad('subnet /64')
            sel = []
            for x in sorted(subs):
                b = int(net.network_address) + (x << 64) if pl == 56 else int(net.network_address)
                if b in bases:
                    raise Bad('overlap')
                bases.add(b)
                sel.append((x, b))
            total += len(sel)
            if total > 2048:
                raise Bad('too many segments')
            scopes.append((sid, sel))
        wins.append((wid, st, scopes))
    wins.sort(key=lambda t: t[0])
    segs = []
    out_wins = []
    for wid, st, scopes in wins:
        ss = sorted(scopes, key=lambda t: t[0])
        idx = []
        for sid, sel in ss:
            per = []
            for x, b in sel:
                nettext = fmt(b) + '/64'
                payload = ('ipv6-evidence-v1\n%d\n%s\n%s\n%s\n' % (seed, wid, sid, nettext)).encode()
                c0 = int.from_bytes(hashlib.sha256(payload).digest()[:8], 'big') | (1 << 63)
                segs.append({'window': wid, 'scope': sid, 'subnet': x, 'base': b,
                             'network': nettext, 'c0': c0})
                per.append(len(segs) - 1)
            idx.append((sid, per))
        out_wins.append((wid, st, idx))
    return {'seed': seed, 'low': low, 'att': att, 'sp': sp, 'to': to,
            'windows': out_wins, 'segments': segs}


def probes(m):
    out = []
    for wid, st, idx in m['windows']:
        q = 0
        for sid, segidx in idx:
            for si in segidx:
                sg = m['segments'][si]
                base = sg['base']
                c0 = sg['c0']
                tg = [('low', i, i) for i in range(1, m['low'] + 1)]
                tg += [('canary', 0, c0), ('canary', 1, c0 ^ 1)]
                for role, slot, iid in tg:
                    t = base | iid
                    for a in range(m['att']):
                        sent = st + q * m['sp']
                        out.append({
                            'id': '%s/%s/%d/%s-%d/%d' % (wid, sid, sg['subnet'], role, slot, a),
                            'window': wid, 'scope': sid, 'subnet': sg['subnet'],
                            'target': fmt(t), 'role': role, 'slot': slot, 'attempt': a,
                            'sent_ms': sent, 'deadline_ms': sent + m['to'],
                            '_seg': si, '_target': t})
                        q += 1
    return out


def plan(path):
    m = load_manifest(path)
    ps = probes(m)
    for p in ps:
        p.pop('_seg')
        p.pop('_target')
    return {'version': 1, 'probes': ps}


REASONS = ['json', 'schema', 'address', 'unknown_probe', 'target_mismatch', 'time', 'icmp']


def replay(manifest_path, responses_path):
    m = load_manifest(manifest_path)
    ps = probes(m)
    index = {p['id']: p for p in ps}
    raw = open(responses_path, 'rb').read()
    if len(raw) > 96 * 1024 * 1024:
        raise Bad('log too big')
    if raw == b'':
        lines = []
    else:
        lines = raw.split(b'\n')
        if lines[-1] == b'':
            lines.pop()
    if len(lines) > 300000:
        raise Bad('too many lines')
    for i, ln in enumerate(lines):
        n = len(ln) + (1 if (i < len(lines) - 1 or raw.endswith(b'\n')) else 0)
        if n > 4096:
            raise Bad('long line')
    accepted = 0
    dups = 0
    diag = []
    seen = set()
    rows = []
    for i, ln in enumerate(lines, 1):
        reason = None
        row = None
        try:
            txt = ln.decode('utf-8')
            row = jload(txt.encode('utf-8'))
        except Exception:
            reason = 'json'
        if reason is None:
            ok = (isinstance(row, dict) and set(row) == {'probe_id', 'received_ms', 'target',
                                                          'source', 'type', 'code'}
                  and isinstance(row['probe_id'], str) and isinstance(row['target'], str)
                  and isinstance(row['source'], str) and row['probe_id'] != ''
                  and len(row['probe_id']) <= 200
                  and isint(row['received_ms']) and isint(row['type']) and isint(row['code']))
            if not ok:
                reason = 'schema'
        tv = sv = None
        if reason is None:
            tv = addr6(row['target'])
            sv = addr6(row['source'])
            if tv is None or sv is None:
                reason = 'address'
        p = None
        if reason is None:
            p = index.get(row['probe_id'])
            if p is None:
                reason = 'unknown_probe'
        if reason is None:
            if tv != p['_target']:
                reason = 'target_mismatch'
        if reason is None:
            if not (p['sent_ms'] <= row['received_ms'] < p['deadline_ms']):
                reason = 'time'
        if reason is None:
            t, c = row['type'], row['code']
            if not ((t == 129 and c == 0) or (t == 1 and 0 <= c <= 6)):
                reason = 'icmp'
        if reason is not None:
            diag.append({'line': i, 'reason': reason})
            continue
        key = (row['probe_id'], row['received_ms'], tv, sv, row['type'], row['code'])
        if key in seen:
            dups += 1
            continue
        seen.add(key)
        accepted += 1
        rows.append((p, tv, sv, row['type'], row['code']))

    segments = []
    for si, sg in enumerate(m['segments']):
        hits = set()
        internal = set()
        external = set()
        per = {}
        for i in range(1, m['low'] + 1):
            per[i] = {'ia': set(), 'ea': set(), 'es': set(), 'ra': set()}
        for (p, tv, sv, t, c) in rows:
            if p['_seg'] != si:
                continue
            if p['role'] == 'canary':
                if (t, c) == (129, 0) and sv == tv:
                    hits.add(p['slot'])
            else:
                per[p['slot']]['ra'].add(p['attempt'])
                if (t, c) == (129, 0) and sv == tv:
                    internal.add(tv)
                    per[p['slot']]['ia'].add(p['attempt'])
                elif t == 1 and 0 <= c <= 6 and sv != tv:
                    external.add(sv)
                    per[p['slot']]['ea'].add(p['attempt'])
                    per[p['slot']]['es'].add(sv)
        overlap = sorted(internal & external)
        if hits == {0, 1}:
            state = 'alias_suspect'
        elif overlap:
            state = 'ambiguous'
        else:
            state = 'usable'
        if state != 'usable':
            exposure = 'excluded'
        elif internal:
            exposure = 'observed_internal_reply'
        else:
            exposure = 'inconclusive'
        targets = []
        for i in range(1, m['low'] + 1):
            d = per[i]
            if state == 'alias_suspect':
                cls = 'alias_suspect'
            elif state == 'ambiguous':
                cls = 'ambiguous'
            elif d['ia'] and d['ea']:
                cls = 'mixed'
            elif d['ia']:
                cls = 'internal'
            elif d['ea']:
                cls = 'external'
            else:
                cls = 'unknown'
            targets.append({
                'address': fmt(sg['base'] | i), 'classification': cls,
                'internal_attempts': sorted(d['ia']), 'external_attempts': sorted(d['ea']),
                'external_sources': [fmt(x) for x in sorted(d['es'])],
                'silent_attempts': [a for a in range(m['att']) if a not in d['ra']]})
        segments.append({
            'window': sg['window'], 'scope': sg['scope'], 'subnet': sg['subnet'],
            'network': sg['network'], 'state': state, 'exposure': exposure,
            'canary_hits': sorted(hits),
            'internal': [fmt(x) for x in sorted(internal)],
            'external': [fmt(x) for x in sorted(external)],
            'overlap': [fmt(x) for x in overlap],
            'targets': targets})
    return {'version': 1, 'accepted_rows': accepted, 'duplicate_rows': dups,
            'diagnostics': diag, 'segments': segments}


def main():
    if sys.argv[1] == 'plan':
        print(json.dumps(plan(sys.argv[2])))
    else:
        print(json.dumps(replay(sys.argv[2], sys.argv[3])))


if __name__ == '__main__':
    try:
        main()
    except Bad as e:
        sys.stderr.write('bad: %s\n' % e)
        sys.exit(2)
